export async function loadRecs(userId: string) {
  if (process.env.NEXT_PUBLIC_FEATURE_RECS !== 'true') return [];
  const base = process.env.RECS_SERVICE_URL;
  const res = await fetch(`${base}/recs/${userId}`);
  return res.ok ? res.json() : [];
}

export const config = {
  port: Number(process.env.PORT ?? 3000),
  cacheHost: process.env.CACHE_HOST ?? 'redis',
  cachePort: 6379,
